import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { RootState } from './store/store';
import {
  moveEvent,
  tickClock,
  setSelectedCategory
} from './store/schedulerSlice';
import { CalendarEvent, Category } from './types';
import { OptimizationControls } from './components/OptimizationControls';
import { MemoizedEventCard, UnmemoizedEventCard } from './components/EventCard';
import { RenderMonitor } from './components/RenderMonitor';

const DAYS: CalendarEvent['day'][] = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];
const CATEGORIES: Category[] = ['Meeting', 'Deadline', 'Focus block', 'Personal'];

export const App: React.FC = () => {
  const dispatch = useDispatch();
  const { events, selectedCategory, config, clockTick } = useSelector(
    (state: RootState) => state.scheduler
  );

  const [renderCounts, setRenderCounts] = useState<Record<string, number>>({});

  // 1. Live Clock simulation (450ms tick to trigger unrelated app state updates)
  useEffect(() => {
    if (!config.liveClock) return;
    const timer = setInterval(() => {
      dispatch(tickClock());
    }, 450);
    return () => clearInterval(timer);
  }, [config.liveClock, dispatch]);

  const handleRecordRender = useCallback((id: string) => {
    setRenderCounts((prev) => ({
      ...prev,
      [id]: (prev[id] || 0) + 1
    }));
  }, []);

  const handleResetCounters = () => {
    setRenderCounts({});
  };

  // 2. Drag & Drop Handlers (useCallback optimization switch)
  const stableDragStart = useCallback(
    (e: React.DragEvent, id: string) => {
      e.dataTransfer.setData('text/plain', id);
    },
    []
  );

  const unstableDragStart = (e: React.DragEvent, id: string) => {
    e.dataTransfer.setData('text/plain', id);
  };

  const activeDragStartHandler = config.useCallbackHandlers
    ? stableDragStart
    : unstableDragStart;

  const handleDrop = (e: React.DragEvent, targetDay: CalendarEvent['day']) => {
    e.preventDefault();
    const id = e.dataTransfer.getData('text/plain');
    if (id) {
      dispatch(moveEvent({ id, targetDay }));
    }
  };

  // 3. Agenda Filter calculation (useMemo optimization switch)
  const filteredEventsMemo = useMemo(() => {
    if (selectedCategory === 'All') return events;
    return events.filter((e) => e.category === selectedCategory);
  }, [events, selectedCategory]);

  const filteredEventsUnmemo =
    selectedCategory === 'All'
      ? events
      : events.filter((e) => e.category === selectedCategory);

  const displayedEvents = config.useMemoFilter
    ? filteredEventsMemo
    : filteredEventsUnmemo;

  const CardComponent = config.useMemoCards
    ? MemoizedEventCard
    : UnmemoizedEventCard;

  return (
    <div className="min-h-screen bg-[#050b18] text-slate-100 p-8 font-sans">
      <header className="mb-6 text-left">
        <h1 className="text-2xl font-bold tracking-tight text-white mb-1.5">
          Interactive Calendar
        </h1>
        <p className="text-xs text-slate-400">
          Drag events between days, then flip the switches below to see, in real
          time, what React.memo, useCallback, and useMemo actually do to re-renders.
        </p>
      </header>

      {/* Optimization Switchboard */}
      <OptimizationControls onResetCounters={handleResetCounters} />

      <div className="flex flex-col lg:flex-row gap-5 items-start">
        {/* Calendar View */}
        <div className="flex-1 bg-[#0b1329] border border-[#1e293b] rounded-xl p-5 w-full shadow-lg">
          <div className="flex flex-wrap items-center justify-between gap-4 mb-5">
            <h2 className="text-xs font-bold uppercase tracking-wider text-slate-300">
              Week View
            </h2>

            {/* Category Filter Pills */}
            <div className="flex items-center space-x-1.5">
              {CATEGORIES.map((cat) => (
                <button
                  key={cat}
                  onClick={() =>
                    dispatch(
                      setSelectedCategory(selectedCategory === cat ? 'All' : cat)
                    )
                  }
                  className={`px-3 py-1 rounded-full text-xs font-medium border transition-colors ${
                    selectedCategory === cat
                      ? 'bg-blue-600 border-blue-500 text-white'
                      : 'border-slate-700/60 bg-[#131b2e] text-slate-400 hover:text-slate-200'
                  }`}
                >
                  {cat}
                </button>
              ))}
            </div>
          </div>

          {/* 7-Day Temporal Layout Grid */}
          <div className="grid grid-cols-7 border border-[#1e293b] rounded-lg overflow-hidden bg-[#070e1f]">
            {DAYS.map((day) => {
              const dayEvents = displayedEvents.filter((e) => e.day === day);

              return (
                <div
                  key={day}
                  onDragOver={(e) => e.preventDefault()}
                  onDrop={(e) => handleDrop(e, day)}
                  className="min-h-[360px] border-r last:border-r-0 border-[#1e293b] p-2 flex flex-col"
                >
                  <span className="text-[11px] font-semibold text-slate-400 mb-3 text-left pl-1">
                    {day}
                  </span>
                  <div className="flex-1 space-y-2">
                    {dayEvents.map((event) => (
                      <CardComponent
                        key={event.id}
                        event={event}
                        onDragStart={activeDragStartHandler}
                        onRenderRecord={handleRecordRender}
                      />
                    ))}
                  </div>
                </div>
              );
            })}
          </div>
        </div>

        {/* Live Re-render Monitor */}
        <RenderMonitor events={events} renderCounts={renderCounts} />
      </div>
    </div>
  );
};

export default App;
